import{directIDs}from'./direct.js?v=13';
import{swipeDirection}from'./gestures.js?v=13';
import{navIcon}from'./icons.js?v=13';
import{scheduleEntries,daySchedule}from'./schedule.js?v=13';
import{loadNova}from'./tv.js?v=13';
import {loadProvider,isConnected} from './providers.js?v=13';
import {competitions,checkedAt,eliteSchedule,eliteTV,eliteMatches,broadcasts,currentTV,gblStandings} from './data.js?v=13';
import {escapeHTML as e,normalizeFootball,calculateTable,athensDay,chooseRound,filterMatches,shiftDay} from './core.js?v=13';
const $=id=>document.getElementById(id);
const shortLabels={volleyball:'Βόλεϊ',football:'Ποδ.',basketball:'Μπασκ.',tv:'TV',matches:'Αγώνες',standings:'Βαθμοί'};
const nav=[['football','⚽','Ποδόσφαιρο'],['basketball','◉','Μπάσκετ'],['volleyball','','Βόλεϊ'],['tv','▣','Τηλεόραση'],['matches','▦','Αγώνες'],['standings','≡','Βαθμολογίες']];
const state={tab:'tv',id:'all-tv',season:'2026-27',matches:[],round:'',search:'',favorites:read('sh-favorites',[]),only:false,request:0,meta:null,tvDate:athensDay(),archive:false};
if(!Array.isArray(state.favorites))state.favorites=[];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
const tvCache=new Map(),scheduleCache=new Map();
const allMatches={id:'all-matches',name:'Όλες οι διοργανώσεις',sport:'all'};
const allTV={id:'all-tv',name:'Όλες οι διοργανώσεις',sport:'all',url:'https://www.novasports.gr/tv-program/'};
function current(){return state.id==='all-matches'?allMatches:state.id==='all-tv'?allTV:competitions.find(c=>c.id===state.id);}
function dateLabel(d){return new Intl.DateTimeFormat('el-GR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Athens'}).format(new Date(d+'T12:00:00+03:00'));}
function timestamp(d){return new Intl.DateTimeFormat('el-GR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Athens'}).format(new Date(d));}
function team(name,badge){let safe=false;try{safe=new URL(badge).protocol==='https:';}catch{}return (safe?'<img class="team-badge" src="'+e(badge)+'" alt="" loading="lazy" referrerpolicy="no-referrer">':'')+e(name);}
function link(url,text){return `<a href="${e(url)}" target="_blank" rel="noopener">${e(text)} ↗</a>`;}
let renderedTab;
function renderNav(){if(renderedTab===state.tab)return;renderedTab=state.tab;for(const id of ['side-nav','top-nav','bottom-nav']){$(id).innerHTML=nav.map(([key,icon,label])=>`<button type="button" data-tab="${key}" aria-label="${label}" class="${state.tab===key?'active':''}" ${state.tab===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${navIcon(key)}</span><span class="full-label">${label}</span><span class="short-label" aria-hidden="true">${shortLabels[key]}</span></button>`).join('');}}
function choices(){const allowed=state.tab==='matches'?[allMatches,...competitions]:state.tab==='tv'?[allTV,...competitions]:competitions.filter(c=>!['football','basketball','volleyball'].includes(state.tab)||c.sport===state.tab);if(!allowed.some(c=>c.id===state.id))state.id=allowed[0].id;$('competition').innerHTML=allowed.map(c=>`<option value="${c.id}" ${c.id===state.id?'selected':''}>${c.name}</option>`).join('');}
function notify(text){$('status').textContent=text;$('status').hidden=!text;}
function empty(title,text,url){return `<div class="empty"><div class="empty-symbol" aria-hidden="true">▦</div><h3>${e(title)}</h3><p>${e(text)}</p>${url?link(url,'Άνοιγμα επίσημης πηγής'):''}</div>`;}
function setRounds(){const rounds=[...new Set(state.matches.map(m=>m.round))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));state.round=chooseRound(state.matches,athensDay());$('round').innerHTML='<option value="">Όλες οι αγωνιστικές</option>'+rounds.map(r=>`<option value="${e(r)}">${e(r)}η αγωνιστική</option>`).join('');$('round').value=state.round;}
async function loadDaily(request,force){
 const season=state.season,selected=state.id;state.dailySources=[];state.dailyErrors=[];let pending=0;
 const list=competitions.filter(c=>selected==='all-matches'||c.id===selected).sort((a,b)=>Number(directIDs.includes(b.id))-Number(directIDs.includes(a.id)));
 const show=()=>{if(request!==state.request)return;state.dailySources=list.map(c=>scheduleCache.get(season+'-'+c.id)).filter(Boolean);state.matches=state.dailySources.flatMap(p=>p.entries);render();notify(pending?'Ενημέρωση…':state.dailyErrors.length?'Ορισμένοι αγώνες δεν μπόρεσαν να ενημερωθούν.':'');};
 let cursor=0;pending=list.length;state.dailyPending=pending;show();
 async function reader(){while(cursor<list.length){const c=list[cursor++];try{let p;if(isConnected(c.id))p=await loadProvider(c.id,season,{force});else{const source=`https://raw.githubusercontent.com/openfootball/football.json/master/${season}/${c.file}.json`,r=await fetch(source,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);p={matches:normalizeFootball(await r.json(),c.id),source,retrievedAt:new Date().toISOString()};}if(request!==state.request)return;if(p.fallback)state.dailyErrors.push(c.name);scheduleCache.set(season+'-'+c.id,{...p,entries:scheduleEntries(p,c)});}catch(error){if(request!==state.request)return;state.dailyErrors.push(c.name);}pending--;state.dailyPending=pending;show();}}
 await Promise.all([reader(),reader(),reader(),reader()]);
}
async function load(force=false){const request=++state.request,c=current(),season=state.season;state.matches=[];state.meta=null;state.loading=true;$('view').innerHTML=empty('Φόρτωση δεδομένων','Ελέγχεται η επιλεγμένη πηγή.');$('refresh').disabled=true;let message='';
 try{
 if(state.tab==='matches'){await loadDaily(request,force);message=$('status').textContent;}else if(isConnected(c.id)&&state.tab!=='tv'){
 const payload=await loadProvider(c.id,season,{force});if(request!==state.request)return;state.matches=payload.matches;state.meta=payload;message=payload.fallback?'Προβάλλονται αποθηκευμένα στοιχεία.':payload.partial?'Μερικό πρόγραμμα.':'';
 }else if(c.file&&state.tab!=='tv'){
  const url=`https://raw.githubusercontent.com/openfootball/football.json/master/${season}/${c.file}.json`,key=`sh-data-${c.id}-${season}`;let cached=read(key,null),payload;
  try{const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();const matches=normalizeFootball(data,c.id);payload={data,retrievedAt:new Date().toISOString(),source:url};if(request!==state.request)return;save(key,payload);state.matches=matches;message='';}
  catch(error){if(!cached){try{const r=await fetch(`./snapshots/${season}-${c.file}.json`);if(r.ok)cached=await r.json();}catch{}}if(!cached)throw error;state.matches=normalizeFootball(cached.data,c.id);payload=cached;message=`Δεν έγινε νέα ανάκτηση (${error.name==='TimeoutError'?'λήξη χρόνου':error.message}). Εμφανίζεται αποθηκευμένο αντίγραφο.`;}
  if(request!==state.request)return;state.meta=payload;
 }else if(season==='2026-27'){
  if(state.tab==='tv'){
   state.tvErrors=[];const feeds=['elite','gbl','sl2','nova'].filter(id=>c.id==='all-tv'||id===c.id||id==='nova');
   const show=()=>{if(request!==state.request)return;state.tvSources=feeds.map(id=>tvCache.get(season+'-'+id)).filter(Boolean);state.matches=state.tvSources.flatMap(p=>p.matches).filter(m=>m.live&&m.date&&m.time&&m.channel&&(c.id==='all-tv'||m.competition===c.id));render();};
   show();notify('Ενημέρωση…');
   await Promise.allSettled(feeds.map(async id=>{try{const p=await(id==='nova'?loadNova():loadProvider(id,season,{force}));if(request!==state.request)return;
    const competition=competitions.find(x=>x.id===id);const matches=id==='nova'?p.matches:p.matches.filter(m=>m.date&&m.time&&m.channel).map(m=>({...m,id:'tv-'+m.id,competition:id,competitionLabel:competition.name,sportLabel:competition.sport==='football'?'Ποδόσφαιρο':'Μπάσκετ',live:true,source:m.source||p.source}));
    tvCache.set(season+'-'+id,{...p,matches});show();
   }catch(error){if(request===state.request){state.tvErrors.push(id+': '+error.message);const old=tvCache.get(season+'-'+id);if(old)tvCache.set(season+'-'+id,{...old,fallback:error.message});}}}));
   if(request!==state.request)return;
  }
  else if(c.id==='elite')state.matches=eliteMatches;
  state.meta={retrievedAt:checkedAt,source:state.tab==='tv'?(c.id==='elite'?eliteTV:c.url):c.id==='elite'?eliteSchedule:c.ranking||c.url};
  if(state.tab==='tv'){state.meta=null;message='';if(state.tvErrors?.length)message='Ορισμένες μεταδόσεις δεν μπόρεσαν να ενημερωθούν.';}else message='Δεν υπάρχει αυτόματη κάλυψη για αυτή την επιλογή.';
 }else{message='Δεν υπάρχει αποθηκευμένη κάλυψη για την επιλεγμένη σεζόν.';}
 }catch(error){if(request!==state.request)return;message=`Η πηγή δεν είναι διαθέσιμη (${error.message}). Δεν εμφανίζονται επινοημένα δεδομένα.`;}
 finally{if(request===state.request){state.loading=false;setRounds();render();notify((navigator.onLine?'':'Εκτός σύνδεσης · ')+message);$('refresh').disabled=false;}}
}
function render(){const c=current();document.body.dataset.tab=state.tab;$('season').closest('label').hidden=state.tab==='tv';renderNav();$('page-title').textContent=state.tab==='standings'?'Βαθμολογίες διοργανώσεων':state.tab==='tv'?'Τηλεοπτικό πρόγραμμα':state.tab==='football'?'Πρόγραμμα ποδοσφαίρου':state.tab==='basketball'?'Πρόγραμμα μπάσκετ':state.tab==='volleyball'?'Πρόγραμμα βόλεϊ':'Όλοι οι αγώνες της ημέρας';$('section-title').textContent=c.name;$('sport-label').textContent=c.sport==='all'?(state.tab==='matches'?'ΟΛΑ ΤΑ ΑΘΛΗΜΑΤΑ':'ΑΘΛΗΤΙΚΗ ΤΗΛΕΟΡΑΣΗ'):c.sport==='football'?'ΠΟΔΟΣΦΑΙΡΟ':c.sport==='volleyball'?'ΒΟΛΕΪ':'ΜΠΑΣΚΕΤ';$('round-label').hidden=['standings','tv','matches'].includes(state.tab);$('tv-day').hidden=!['tv','matches'].includes(state.tab);$('day-label').textContent=state.tab==='matches'?'Ημερήσιο πρόγραμμα':'Ζωντανές μεταδόσεις';$('tv-archive').closest('label').hidden=true;$('tv-date').value=state.tvDate;$('coverage').textContent=state.meta?.partial?'Μερική κάλυψη · TheSportsDB':c.id==='sl'?'':' ';
 $('coverage').hidden=!state.meta?.partial&&!['matches','tv'].includes(state.tab);
 if(state.tab==='matches')$('coverage').textContent='Όλα τα αθλήματα · Ανά ημέρα';else if(state.tab==='tv')$('coverage').textContent='Μόνο ζωντανές';
 const meta=state.meta;$('source-note').innerHTML=meta?`Σεζόν 2026–27 · Ανάκτηση / έλεγχος: ${e(timestamp(meta.retrievedAt))} (Ελλάδα).<br>${link(meta.source,'Πρωτογενής πηγή')}<br>${c.file||c.id==='sl'?'Τα ωράρια της κοινοτικής πηγής παραλείπονται επειδή δεν δηλώνουν αξιόπιστα ζώνη ώρας. Τα σκορ εμφανίζονται μόνο όταν τα επιστρέφει η πηγή.':'Το στιγμιότυπο μπορεί να έχει αλλάξει. Επιβεβαίωσε στην επίσημη πηγή πριν τον αγώνα.'}`:'Δεν έχει ανακτηθεί σύνολο δεδομένων για αυτή την επιλογή.';
 if(state.tab==='tv')$('source-note').innerHTML=(state.tvSources||[]).map(p=>`Έλεγχος: ${e(timestamp(p.retrievedAt))} · ${link(p.source,'Πηγή μεταδόσεων')}${p.fallback?' · Αποθηκευμένο αντίγραφο':''}<br>${e(p.copyright||'')}`).join('<br>')||'Δεν ανακτήθηκε πηγή μεταδόσεων.';
 if(state.tab==='matches')$('source-note').innerHTML=(state.dailySources||[]).map(p=>`${link(p.source,'Πηγή προγράμματος')} · ${e(timestamp(p.retrievedAt))}${p.fallback?' · Αποθηκευμένο αντίγραφο':''}<br>${e(p.copyright||'')}${p.terms?' · '+link(p.terms,'Άδεια / όροι'):''}`).join('<br>')||'Αναζητούνται διαθέσιμες πηγές.';
 if(meta?.copyright)$('source-note').innerHTML+=`<br>${e(meta.copyright)} ${meta.terms?link(meta.terms,'Όροι προσωπικής χρήσης'):''}`;
 if(state.tab==='standings'){renderTable(c);return;}
 let matches=filterMatches(state.matches,{round:['tv','matches'].includes(state.tab)?'':state.round,search:state.search,favoritesOnly:state.only,favorites:state.favorites,date:state.tab==='matches'||state.tab==='tv'&&!state.archive?state.tvDate:''});
 matches.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'').localeCompare(b.time||''));
 if(state.tab==='matches')matches=daySchedule(matches,state.tvDate);
 if(!matches.length){const hasData=state.matches.length>0;if(state.tab==='matches'){if(state.dailyPending&&!state.dailySources?.length){$('view').innerHTML=empty('Φόρτωση ημερήσιου προγράμματος','Οι πρώτοι αγώνες θα εμφανιστούν μόλις απαντήσει μια πηγή.');return;}$('view').innerHTML=empty('Δεν βρέθηκαν αγώνες για αυτή την ημέρα','Επίλεξε άλλη ημερομηνία ή διοργάνωση. Τα στοιχεία εμφανίζονται σταδιακά καθώς απαντούν οι πηγές. Αγώνες χωρίς ορισμένη ημερομηνία δεν εμφανίζονται στην ημερήσια λίστα.');return;}if(state.tab==='tv'){$('view').innerHTML=empty(state.loading?'Φόρτωση…':'Δεν βρέθηκαν ζωντανές μεταδόσεις',state.loading?'':dateLabel(state.tvDate));return;}$('view').innerHTML=empty(hasData?'Δεν βρέθηκαν αγώνες':'Δεν υπάρχουν διαθέσιμα στοιχεία',hasData?'Άλλαξε αγωνιστική, αναζήτηση ή το φίλτρο αγαπημένων.':state.tab==='tv'?'Δεν υπάρχει επιβεβαιωμένη λίστα μεταδόσεων για αυτή τη διοργάνωση και σεζόν. Δες τα επίσημα προγράμματα καναλιών δεξιά.':c.note||'Η επιλεγμένη πηγή δεν επέστρεψε πρόγραμμα.',c.url);return;}
 let day='';let html=state.tab==='matches'?`<div class="daily-summary"><strong>${matches.length} αγώνες</strong><span>${new Set(matches.map(m=>m.competition)).size} διοργανώσεις · ${e(dateLabel(state.tvDate))}</span></div>`:state.meta?.partial?`<div class="notice">${e(state.meta.notice)} ${link('https://www.thesportsdb.com/','Πηγή: TheSportsDB')}</div>`:'';
 for(const m of matches){if(day!==m.date){day=m.date;html+=`<div class="match-date">${e(day?dateLabel(day):'Ημερομηνία δεν έχει οριστεί')}</div>`;}const saved=state.favorites.includes(m.id);html+=`<article class="match"><div class="match-time">${e(m.time||'—')}</div><div class="match-info"><div class="fixture-title">${team(m.home,m.homeBadge)} <span class="fixture-dash">–</span> ${team(m.away,m.awayBadge)}</div>${['tv','matches'].includes(state.tab)?`<div class="broadcast-meta">${e([m.sportLabel,m.competitionLabel].filter(Boolean).join(' · '))}</div>`:''}${state.tab!=='tv'&&Array.isArray(m.score)?`<div class="match-score"><strong>${e(m.score.join(' – '))}</strong><span>${m.scoreState==='live'?'● LIVE':m.scoreState==='final'?(c.sport==='volleyball'||m.sportLabel==='Βόλεϊ'?'Τελικό · σετ':'Τελικό'):'Σκορ πηγής'}</span></div>`:''}${m.channel?`<div class="broadcast-channel"><strong>${e(m.channel)}</strong>${m.streamURL?' '+link(m.streamURL,'Δες'):''}</div>`:''}</div><button class="star ${saved?'saved':''}" data-favorite="${e(m.id)}" aria-pressed="${saved}" aria-label="${saved?'Αφαίρεση από':'Προσθήκη στα'} αγαπημένα: ${e(m.home)} – ${e(m.away)}">${saved?'★':'☆'}</button></article>`;}
 $('view').innerHTML=html;
}
function renderTable(c){
 const meta=state.meta,football=c.sport==='football';let rows=meta?.standings||[],computed=false;
 if(!rows.length&&(c.file||c.id==='sl')&&state.matches.length){rows=calculateTable(state.matches,athensDay());computed=true;}
 if(!rows.length){$('view').innerHTML=empty('Δεν υπάρχει διαθέσιμη βαθμολογία',c.note||'Δεν έχει συνδεθεί πηγή για αυτή τη σεζόν.',c.ranking||c.url);return;}
 if(meta?.standingsSource)$('source-note').innerHTML+=`<br>${link(meta.standingsSource,'Πηγή κατάταξης')}`;
 const q=state.search.toLocaleLowerCase('el');rows=rows.filter(r=>r.team.toLocaleLowerCase('el').includes(q));
 const percent=['el','eurocup'].includes(c.id);
 const notice=computed?'Ενδεικτική βαθμολογία · Δεν περιλαμβάνει ποινές ή ειδικές ισοβαθμίες.':'';
 $('view').innerHTML=`${notice?`<div class="notice">${e(notice)}</div>`:''}<div class="table-scroll"><table><caption class="fine">${e(c.name)} · 2026–27</caption><thead><tr><th scope="col">#</th><th scope="col">Ομάδα</th><th scope="col">Αγ.</th><th scope="col">Ν</th>${football?'<th scope="col">Ι</th>':''}<th scope="col">Η</th><th scope="col">${percent?'% Ν':'Βαθ.'}</th></tr></thead><tbody>${rows.map((r,i)=>`${r.group&&r.group!==rows[i-1]?.group?`<tr><th colspan="${football?7:6}" scope="rowgroup">${e(r.group)}</th></tr>`:''}<tr><td>${r.rank}</td><td>${team(r.team,r.badge||state.matches.find(m=>m.home===r.team)?.homeBadge||state.matches.find(m=>m.away===r.team)?.awayBadge)}</td><td>${r.played}</td><td>${r.wins}</td>${football?`<td>${r.draws}</td>`:''}<td>${r.losses}</td><td>${percent?e(r.winRate||'—'):r.points}</td></tr>`).join('')}</tbody></table></div>`;
}
function showHelp(){const cards=competitions.map(c=>`<div><b>${e(c.name)}</b><p>${e(c.file?'Δωρεάν openfootball / CC0. Δοκιμάστηκε HTTP 200 και CORS *. Αυτόματη ανάκτηση όταν ανοίγεις τη διοργάνωση, με αποθηκευμένο αντίγραφο αν αποτύχει. Κοινοτικά στοιχεία, όχι επίσημη πιστοποίηση.':c.note)}</p>${link(c.url,'Επίσημη ιστοσελίδα')}</div>`).join('');$('help-content').innerHTML=`<h3>Εγκατάσταση σε Android</h3><p>Άνοιξε τον σύνδεσμο GitHub Pages με Chrome. Δεν απαιτείται σύνδεση. Πάτησε «Εγκατάσταση εφαρμογής» ή μενού ⋮ → «Προσθήκη στην αρχική οθόνη» → «Εγκατάσταση». Η επιλογή εξαρτάται από τον browser. Δεν απαιτείται app store.</p><h3>Εγκατάσταση σε PC</h3><p>Σε Chrome ή Edge, άνοιξε τον ίδιο σύνδεσμο και πάτησε το εικονίδιο εγκατάστασης στη γραμμή διευθύνσεων ή την επιλογή εγκατάστασης από το μενού. Τοπικά εκκινείται και από localhost μέσω του παρεχόμενου οδηγού.</p><h3>Offline & ιδιωτικότητα</h3><p>Μετά την πρώτη επιτυχή φόρτωση, το κέλυφος και τα αποθηκευμένα δεδομένα παραμένουν στη συσκευή. Τα αγαπημένα αποθηκεύονται τοπικά χωρίς συγχρονισμό. Οι εξωτερικές πηγές και η αρχική σύνδεση χρειάζονται internet. Οι πηγές ελέγχονται όταν ανοίγεις ή ανανεώνεις τη διοργάνωση. Χωρίς διαφημίσεις ή analytics στην εφαρμογή.</p><h3>Τι έχει ελεγχθεί</h3><p>Έλεγχος πηγών: 20/10/2026. Δεν χρησιμοποιούνται placeholders αγώνων, βαθμολογιών ή μεταδόσεων. Τα σήματα ομάδων προέρχονται από τις πηγές όπου παρέχονται. Το αρχικό screenshot δεν ήταν προσβάσιμο στη μεταφερμένη συνομιλία· η διάταξη ακολουθεί τη γραπτή περιγραφή.</p><div class="help-grid">${cards}</div><h3>Τηλεόραση</h3><p>Η ημερήσια λίστα ανανεώνεται από τις ρητές αναφορές μετάδοσης ΕΟΚ, ΕΣΑΚΕ και SL2, και από το δημοσιευμένο ημερήσιο πρόγραμμα Novasports που διαβάζεται απευθείας στον browser. Στη λίστα εμφανίζονται μόνο ρητά δηλωμένες ζωντανές μεταδόσεις. Οι επαναλήψεις και οι καταχωρίσεις χωρίς ένδειξη ζωντανής μετάδοσης αποκλείονται. Οι πηγές φορτώνονται παράλληλα και η λίστα εμφανίζεται σταδιακά, χωρίς να περιμένει την πιο αργή. Δεν δημοσιεύεται αρχείο EPG στο repository. Οι υπόλοιπες μεταδόσεις ελέγχονται στα επίσημα προγράμματα καναλιών. Δεν υπάρχει πλήρης δωρεάν ελληνικός EPG συνδεδεμένος. Δεν συμπεραίνουμε κανάλι από τα δικαιώματα μιας διοργάνωσης. Οι δοκιμές λανθασμένων URL COSMOTE / Nova επέστρεψαν 404 και αντικαταστάθηκαν με τους επίσημους συνδέσμους των προγραμμάτων.</p><p>${link('https://github.com/openfootball/football.json/blob/master/LICENSE.md','Άδεια openfootball CC0')} · ${link('https://www.football-data.org/coverage','Κάλυψη football-data.org')}</p>`;$('help-dialog').showModal();}
function selectTab(key){if(state.tab===key)return;state.tab=key;if(key==='tv')state.id='all-tv';if(key==='matches')state.id='all-matches';choices();load();}
for(const id of ['side-nav','top-nav','bottom-nav'])$(id).addEventListener('click',event=>{const b=event.target.closest('[data-tab]');if(b)selectTab(b.dataset.tab);});
$('competition').addEventListener('change',()=>{state.id=$('competition').value;load();});$('round').addEventListener('change',()=>{state.round=$('round').value;render();});$('search').addEventListener('input',()=>{state.search=$('search').value;render();});$('favorites').addEventListener('change',()=>{state.only=$('favorites').checked;render();});
$('view').addEventListener('click',event=>{const b=event.target.closest('[data-favorite]');if(!b)return;const id=b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];if(!save('sh-favorites',state.favorites))notify('Τα αγαπημένα λειτουργούν προσωρινά· η αποθήκευση του browser δεν είναι διαθέσιμη.');render();});
$('refresh').addEventListener('click',()=>load(true));$('help').onclick=showHelp;$('data-help').onclick=showHelp;$('close-help').onclick=()=>$('help-dialog').close();
let installPrompt;
const standaloneMode=window.matchMedia('(display-mode: standalone)');
function updateInstallButton(){ $('install').hidden=standaloneMode.matches||navigator.standalone===true||read('sh-installed',false)===true; }
updateInstallButton();standaloneMode.addEventListener('change',updateInstallButton);
window.addEventListener('storage',event=>{if(event.key==='sh-installed')updateInstallButton();});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;save('sh-installed',false);updateInstallButton();});
$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else showHelp();};
window.addEventListener('appinstalled',()=>{installPrompt=null;save('sh-installed',true);$('install').hidden=true;});

window.addEventListener('offline',()=>notify('Εκτός σύνδεσης · τα δεδομένα είναι αποθηκευμένα στιγμιότυπα. Οι εξωτερικές πηγές χρειάζονται internet.'));window.addEventListener('online',()=>load());
$('today').textContent=new Intl.DateTimeFormat('el-GR',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Athens'}).format(new Date());
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('Δεν ενεργοποιήθηκε η offline λειτουργία. Άνοιξε την εφαρμογή μέσω HTTPS ή localhost.'));
function changeDay(delta){state.tvDate=shiftDay(state.tvDate,delta);state.archive=false;$('tv-archive').checked=false;render();}
$('tv-date').onchange=()=>{if($('tv-date').value){state.tvDate=$('tv-date').value;state.archive=false;render();}};
$('prev-day').onclick=()=>changeDay(-1);$('next-day').onclick=()=>changeDay(1);
$('today-button').onclick=()=>{state.tvDate=athensDay();state.archive=false;render();};
function installSwipe(element,onSwipe){let start; element.addEventListener('touchstart',event=>{if(event.touches.length!==1||event.target.closest('input,select,a,button,summary,.table-scroll')){start=null;return;}start={x:event.touches[0].clientX,y:event.touches[0].clientY};},{passive:true});element.addEventListener('touchend',event=>{if(!start||!event.changedTouches.length)return;const end={x:event.changedTouches[0].clientX,y:event.changedTouches[0].clientY};const direction=swipeDirection(start,end);start=null;if(direction)onSwipe(direction);},{passive:true});element.addEventListener('touchcancel',()=>{start=null;},{passive:true});}
installSwipe($('view'),direction=>{if(['tv','matches'].includes(state.tab))changeDay(direction);else{const i=nav.findIndex(n=>n[0]===state.tab),next=nav[i+direction];if(next)selectTab(next[0]);}});
document.addEventListener('keydown',event=>{if(!['tv','matches'].includes(state.tab)||event.target.closest('input,select,textarea,button,a,summary')||event.altKey||event.ctrlKey||event.metaKey)return;if(event.key==='ArrowLeft')changeDay(-1);if(event.key==='ArrowRight')changeDay(1);});
setInterval(async()=>{if(document.hidden||state.loading||state.refreshing||!['matches','football','basketball','volleyball'].includes(state.tab))return;if(state.tab==='matches'&&state.tvDate!==athensDay())return;state.refreshing=true;const request=state.request;try{if(state.tab==='matches')await loadDaily(request,true);else if(isConnected(state.id)){const p=await loadProvider(state.id,state.season,{force:true});if(request===state.request){state.matches=p.matches;state.meta=p;render();}}}catch{}finally{state.refreshing=false;}},90000);
choices();renderNav();load();
